import React, { useState } from 'react';
import { User, MapPin, Search, X, Navigation, Calendar, Clock, HardDrive, ShieldCheck, Zap, ChevronRight, History, PlayCircle, Truck } from 'lucide-react';

const WorkersTab = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedWorker, setSelectedWorker] = useState(null);
  const [activeFilter, setActiveFilter] = useState('INFO');

  const workers = [
    { id: 'WK-102', name: 'KESHAV RAO', role: 'COLLECTION_LEAD', vehicle: 'TRUCK_A_99', status: 'ON_ROUTE', shift: '06:00 - 14:00' },
    { id: 'WK-205', name: 'PRIYA DAS', role: 'DRIVER_LEVEL_2', vehicle: 'TRUCK_B_42', status: 'ON_BREAK', shift: '08:00 - 16:00' },
    { id: 'WK-088', name: 'MOHIT VERMA', role: 'SUPERVISOR', vehicle: 'JEEP_S_01', status: 'OFFLINE', shift: '09:00 - 17:00' },
  ];

  const workerDetails = {
    currentRoute: {
      id: 'RT-404',
      name: 'GANDHI_NAGAR_CIRCUIT',
      progress: '65%',
      stops: ['STOP_1: APARTMENT_A', 'STOP_2: PLOT_B', 'STOP_3: MARKET_SQ'],
      eta: '45 MIN'
    },
    history: [
      { date: '21 MAR', route: 'SILICON_VALLEY_A', status: 'COMPLETED', performance: '100%' },
      { date: '20 MAR', route: 'OLD_TOWN_B', status: 'COMPLETED', performance: '98%' },
    ],
    schedule: [
      { day: 'MON - FRI', task: 'RESIDENTIAL_PICKUP', zone: 'ZONE_A' },
      { day: 'SAT', task: 'EQUIPMENT_MAINTENANCE', zone: 'DEPOT_HQ' }
    ]
  };

  return (
    <div className="w-full h-full flex flex-col gap-6 font-black italic uppercase tracking-tighter select-none">

      {/* 🛠️ WORKER REGISTRY HEADER (Seed Green) */}
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-[#CAD23C] p-6 rounded-[32px] border-[5px] border-[#47510B] shadow-[8px_8px_0_0_#47510B] shrink-0">
        <div className="flex items-center gap-4 text-[#47510B]">
          <Truck size={40} />
          <h1 className="text-3xl leading-none">WORKER_OPERATIONS</h1>
        </div>
        <div className="relative w-full md:w-96">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-[#47510B]/40" size={20} />
          <input 
            type="text" 
            placeholder="FIND_STAFF_ID..." 
            className="w-full bg-white border-[4px] border-[#47510B] rounded-2xl p-4 pl-12 outline-none shadow-[4px_4px_0_0_#47510B]"
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* 👷 WORKER CARDS: pb-28 for bottom clearance */}
      <div className="flex-grow overflow-y-auto pr-2 pb-28 custom-scrollbar grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
        {workers.map(w => (
          <div 
            key={w.id} 
            onClick={() => setSelectedWorker(w)} 
            className="bg-white border-[4px] border-[#47510B] p-6 rounded-[35px] shadow-[6px_6px_0_0_#47510B] hover:translate-x-1 hover:shadow-[10px_10px_0_0_#A1AED1] transition-all cursor-pointer flex justify-between items-center group min-h-[110px]"
          >
            <div>
              <p className="text-[10px] text-[#AB1717] mb-1 font-bold">{w.id} // {w.status}</p>
              <h3 className="text-2xl text-[#47510B] leading-tight truncate">{w.name}</h3>
              <p className="text-[10px] opacity-50 bg-[#FDFAD8] px-2 py-0.5 rounded border border-[#47510B]/20 inline-block">{w.role}</p>
            </div>
            <div className="bg-[#47510B] p-2 rounded-xl text-[#CAD23C]">
              <ChevronRight size={24} strokeWidth={3} />
            </div>
          </div>
        ))}
      </div>

      {/* 🏗️ WORKER DOSSIER MODAL */}
      {selectedWorker && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 md:p-10">
          <div className="absolute inset-0 bg-[#47510B]/80 backdrop-blur-sm animate-in fade-in duration-200" onClick={() => setSelectedWorker(null)} />

          <div className="relative w-full max-w-5xl h-[85vh] bg-[#FDFAD8] border-[6px] border-[#47510B] rounded-[50px] shadow-[20px_20px_0_0_#000] overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">

            {/* MODAL HEADER: SEED GREEN THEME */}
            <div className="bg-[#CAD23C] p-8 text-[#47510B] flex justify-between items-center border-b-[6px] border-[#47510B] shrink-0 relative">
                <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none"><HardDrive size={180}/></div>
                <div className="flex gap-6 items-center relative z-10">
                    <div className="w-16 h-16 bg-white border-4 border-[#47510B] rounded-[20px] flex items-center justify-center shadow-[4px_4px_0_0_#47510B]">
                        <User size={36} strokeWidth={3} />
                    </div>
                    <div>
                        <span className="bg-[#47510B] text-white px-3 py-1 rounded-full text-[10px] inline-block mb-1">ID: {selectedWorker.id}</span>
                        <h2 className="text-3xl md:text-5xl leading-none">{selectedWorker.name}</h2>
                    </div>
                </div>
                <button onClick={() => setSelectedWorker(null)} className="bg-[#AB1717] border-4 border-white p-3 rounded-2xl hover:scale-110 transition-all shadow-[4px_4px_0_0_#000] shrink-0"><X size={28} color="white" /></button>
            </div>

            {/* MODAL NAV: BLUE LINEN */}
            <div className="bg-[#A1AED1] p-2 flex gap-2 overflow-x-auto no-scrollbar shrink-0 border-b-[4px] border-[#47510B]">
              {[
                { id: 'INFO', label: 'WORK_PROFILE', icon: <ShieldCheck size={16}/> },
                { id: 'ROUTES', label: 'ACTIVE_MAP', icon: <Navigation size={16}/> },
                { id: 'HISTORY', label: 'LOG_HISTORY', icon: <History size={16}/> },
                { id: 'SCHEDULE', label: 'DUTY_ROSTER', icon: <Calendar size={16}/> }
              ].map(f => (
                <button 
                  key={f.id}
                  onClick={() => setActiveFilter(f.id)}
                  className={`flex items-center gap-3 px-6 py-3 rounded-2xl text-[11px] font-black transition-all border-4 whitespace-nowrap ${activeFilter === f.id ? 'bg-[#FFF24D] text-[#47510B] border-[#47510B] shadow-[4px_4px_0_0_#000]' : 'bg-white/30 text-[#47510B] border-transparent hover:border-[#47510B]'}`}
                >
                  {f.icon} {f.label}
                </button>
              ))}
            </div>

            {/* CONTENT AREA */}
            <div className="flex-grow p-8 overflow-y-auto pb-16 custom-scrollbar">

              {/* INFO TAB */}
              {activeFilter === 'INFO' && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-in slide-in-from-bottom-4">
                    <div className="bg-white p-6 rounded-[35px] border-4 border-[#47510B] shadow-[6px_6px_0_0_#CAD23C]">
                      <label className="text-[#AB1717] text-[10px] block mb-2 font-bold uppercase tracking-widest">ASSIGNED_UNIT</label>
                      <p className="text-3xl text-[#47510B]">{selectedWorker.vehicle}</p>
                      <p className="text-[10px] mt-2 opacity-50 underline decoration-2 decoration-[#CAD23C]">MAINTENANCE_STATUS: OPTIMAL</p>
                    </div>
                    <div className="bg-white p-6 rounded-[35px] border-4 border-[#47510B] shadow-[6px_6px_0_0_#A1AED1]">
                      <label className="text-[#AB1717] text-[10px] block mb-2 font-bold uppercase tracking-widest">SHIFT_WINDOW</label>
                      <p className="text-3xl text-[#47510B]">{selectedWorker.shift}</p>
                      <p className="text-[10px] mt-2 opacity-50 underline decoration-2 decoration-[#FF5B03]">ACTIVE_DUTY_HOURS: 06.5</p>
                    </div>
                </div>
              )}

              {/* ROUTES TAB */}
              {activeFilter === 'ROUTES' && (
                <div className="flex flex-col lg:flex-row gap-8 animate-in slide-in-from-right-4">
                  <div className="flex-1 space-y-4">
                    <div className="bg-[#47510B] p-6 rounded-[35px] text-white border-b-[8px] border-[#CAD23C] shadow-[10px_10px_0_0_#000]">
                      <p className="text-[10px] text-[#CAD23C]">CURRENTLY_NAVIGATING</p>
                      <h4 className="text-3xl italic">{workerDetails.currentRoute.name}</h4>
                      <div className="mt-6 w-full bg-black/20 h-4 rounded-full overflow-hidden border-2 border-white/20">
                        <div className="bg-[#FFF24D] h-full" style={{ width: workerDetails.currentRoute.progress }}></div>
                      </div>
                      <p className="text-right text-[10px] mt-2 font-black">{workerDetails.currentRoute.progress} COMPLETE</p>
                    </div>
                    <div className="space-y-2">
                      {workerDetails.currentRoute.stops.map((stop, i) => (
                        <div key={i} className="bg-white border-2 border-[#47510B] p-3 rounded-xl flex gap-3 items-center">
                          <MapPin size={16} className="text-[#AB1717]" />
                          <p className="text-xs font-bold text-[#47510B]">{stop}</p>
                        </div>
                      ))}
                    </div>
                  </div>
                  <div className="lg:w-1/3 bg-[#FF5B03] border-[6px] border-[#47510B] rounded-[40px] p-6 text-white flex flex-col items-center justify-center text-center shadow-[10px_10px_0_0_#000]">
                     <PlayCircle size={48} className="mb-3 animate-pulse" />
                     <h3 className="text-2xl">LIVE_TRACKING</h3>
                     <p className="text-[10px] mt-2 font-bold uppercase italic">ETA_TO_BASE: {workerDetails.currentRoute.eta}</p>
                  </div>
                </div>
              )}

              {/* HISTORY TAB */}
              {activeFilter === 'HISTORY' && (
                <div className="space-y-4 animate-in slide-in-from-bottom-4">
                  {workerDetails.history.map((h, i) => (
                    <div key={i} className="bg-white border-4 border-[#47510B] p-5 rounded-[25px] flex justify-between items-center shadow-[5px_5px_0_0_#CAD23C]">
                      <div className="flex items-center gap-4 min-w-0">
                        <div className="bg-[#A1AED1] p-2 rounded-lg text-[#47510B] border-2 border-black shrink-0"><Clock size={20}/></div>
                        <div>
                          <h4 className="text-xl text-[#47510B] truncate">{h.route}</h4>
                          <p className="text-[10px] opacity-40 font-bold italic">{h.date} // EFFICIENCY: {h.performance}</p>
                        </div>
                      </div>
                      <span className="text-[10px] font-black bg-[#47510B] text-white px-5 py-2 rounded-xl shrink-0">ARCHIVED</span>
                    </div>
                  ))}
                </div>
              )}

              {/* SCHEDULE TAB */}
              {activeFilter === 'SCHEDULE' && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-in slide-in-from-right-4">
                   {workerDetails.schedule.map((s, i) => (
                    <div key={i} className="bg-[#FFF24D] border-4 border-[#47510B] p-6 rounded-[35px] shadow-[8px_8px_0_0_#47510B]">
                       <Zap size={28} className="mb-2 text-[#FF5B03]" />
                       <h3 className="text-2xl text-[#47510B]">{s.task}</h3>
                       <p className="text-sm opacity-60 mt-1">{s.day} // {s.zone}</p>
                    </div>
                   ))}
                </div>
              )}

            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default WorkersTab;
